196	func addName(list []string, name string) []string {
197		index := sort.SearchStrings(list, name)
198		if index < len(list) && list[index] == name {
199			return list
200		}
201		list = append(list, "")
202		copy(list[index+1:], list[index:])
203		list[index] = name
204		return list
205	}
