1	// Package chainledger graph structure rules shared by every graph reader.
2	//
3	// Both on-disk graph files (UnmarshalGraphFile) and the graph embedded in a
4	// snapshot (ParseSnapshot) describe the same thing: a set of dataset names and
5	// each dataset's direct upstreams. The rules below are the single authority for
6	// turning that description into the validated, normalized adjacency both
7	// readers build on, so the two file formats can never disagree about whether
8	// one graph is legal or about which lineage relations it expresses:
9	//
10	//   - an empty dataset name is rejected;
11	//   - a dataset declared more than once is rejected;
12	//   - an upstream that is not itself a declared dataset is rejected, with the
13	//     referrer and the referenced name both in the error;
14	//   - a direct self-dependency or any indirect dependency cycle is rejected,
15	//     with the datasets on the cycle named;
16	//   - names are case-sensitive and surrounding whitespace is kept verbatim;
17	//   - record order and upstream order are irrelevant, duplicate upstreams count
18	//     as one relationship, and an empty upstream list marks a root, so an
19	//     empty graph stays legal.
20	//
21	// The snapshot-only envelope rules (required fields, format version, content
22	// identifier, duplicate known fields) live in snapshot.go; this file is only
23	// the common graph structure.
24	package chainledger
25	
26	import (
27		"fmt"
28		"sort"
29		"strings"
30	)
31	
32	// adjacency maps a dataset name to its sorted, duplicate-free parent names.
33	type adjacency map[string][]string
34	
35	// normalizeDatasets builds the normalized parent adjacency from parsed dataset
36	// records. It rejects empty dataset names and datasets declared more than
37	// once; every surviving upstream list is sorted and deduplicated. It does not
38	// check that upstreams resolve to a declared dataset; use
39	// validateAdjacencyReferences for that.
40	func normalizeDatasets(datasets []GraphDataset) (adjacency, error) {
41		adj := make(adjacency, len(datasets))
42		for _, ds := range datasets {
43			if ds.Name == "" {
44				return nil, fmt.Errorf("%w: graph contains a dataset with an empty name", ErrInvalidArgument)
45			}
46			if _, exists := adj[ds.Name]; exists {
47				return nil, fmt.Errorf("%w: dataset %q is declared more than once in the graph", ErrInvalidArgument, ds.Name)
48			}
49			adj[ds.Name] = uniqueSorted(ds.Upstreams)
50		}
51		return adj, nil
52	}
53	
54	// validateAdjacencyReferences rejects an edge whose upstream is not a declared
55	// dataset. Referrers are visited in sorted order with their parents sorted, so
56	// the first reported (referrer, upstream) pair is stable regardless of map
57	// iteration or record order.
58	func validateAdjacencyReferences(adj adjacency) error {
59		names := make([]string, 0, len(adj))
60		for name := range adj {
61			names = append(names, name)
62		}
63		sort.Strings(names)
64		for _, name := range names {
65			for _, parent := range adj[name] {
66				if _, ok := adj[parent]; !ok {
67					return fmt.Errorf("%w: dataset %q references upstream %q which is not registered", ErrNotFound, name, parent)
68				}
69			}
70		}
71		return nil
72	}
73	
74	// validateGraphStructureFromFile runs every graph-structure rule shared by the
75	// file readers: it normalizes the records, rejects empty names, duplicate
76	// datasets, and unregistered upstreams, then rejects cycles. The returned
77	// adjacency is the canonical form of the graph's semantics.
78	func validateGraphStructureFromFile(datasets []GraphDataset) (adjacency, error) {
79		adj, err := normalizeDatasets(datasets)
80		if err != nil {
81			return nil, err
82		}
83		if err := validateAdjacencyReferences(adj); err != nil {
84			return nil, err
85		}
86		if err := validateAcyclic(adj); err != nil {
87			return nil, err
88		}
89		return adj, nil
90	}
91	
92	// validateAcyclic reports an error if the parent adjacency contains a cycle
93	// (including a dataset that depends on itself). The error message names the
94	// datasets involved.
95	func validateAcyclic(adj adjacency) error {
96		const (
97			white = 0
98			gray  = 1
99			black = 2
100		)
101		color := make(map[string]int, len(adj))
102		var stack []string
103	
104		var dfs func(node string) error
105		dfs = func(node string) error {
106			color[node] = gray
107			stack = append(stack, node)
108			for _, parent := range adj[node] {
109				switch color[parent] {
110				case gray:
111					// parent is an ancestor of node in the current DFS path, so
112					// following parent edges from parent leads back to parent.
113					idx := 0
114					for stack[idx] != parent {
115						idx++
116					}
117					cycle := make([]string, 0, len(stack)-idx+1)
118					cycle = append(cycle, stack[idx:]...)
119					cycle = append(cycle, parent)
120					return fmt.Errorf("%w: dependency cycle %s", ErrCycle, strings.Join(cycle, " -> "))
121				case white:
122					if err := dfs(parent); err != nil {
123						return err
124					}
125				}
126			}
127			color[node] = black
128			stack = stack[:len(stack)-1]
129			return nil
130		}
131	
132		// Iterate over a sorted snapshot so the first reported cycle is stable
133		// across runs regardless of map iteration order.
134		names := make([]string, 0, len(adj))
135		for name := range adj {
136			names = append(names, name)
137		}
138		sort.Strings(names)
139		for _, name := range names {
140			if color[name] == white {
141				if err := dfs(name); err != nil {
142					return err
143				}
144			}
145		}
146		return nil
147	}
148	
149	// lineageFromAdjacency rebuilds the in-memory graph from validated, normalized
150	// parent adjacency: children are derived from the parent edges, so every
151	// parent/child pair corresponds and both lists stay sorted and duplicate-free.
152	// The result is independent of the caller's record slices.
153	func lineageFromAdjacency(adj adjacency) map[string]*Lineage {
154		graph := make(map[string]*Lineage, len(adj))
155		for name, parents := range adj {
156			graph[name] = &Lineage{
157				Dataset: name,
158				Parents: append([]string(nil), parents...),
159			}
160		}
161		for name, parents := range adj {
162			for _, parent := range parents {
163				graph[parent].Children = append(graph[parent].Children, name)
164			}
165		}
166		for name := range graph {
167			graph[name].Children = uniqueSorted(graph[name].Children)
168		}
169		return graph
170	}
171

